output.arguments:
{"code":"def transform(grid):
    g=[r[:] for r in grid]
    h=len(g); w=len(g[0])
    # A horizontal gray bar makes the colored cells drop to its row.
    bars=[r for r in range(h) if sum(x==5 for x in g[r])==w]
    if bars:
        r=bars[-1]
        for i in range(h):
            for j in range(w):
                if g[i][j]==1:
                    g[i][j]=0
                    g[r][j]=1
        return g
    # Otherwise a vertical gray column sends the 1 to the right edge.
    for i in range(h):
        for j in range(w):
            if g[i][j]==1:
                g[i][j]=0; g[i][w-1]=1
    return g"}

